{
  "summary": "Camera alert overlaps XV-2104 (61.5%) and F-205 (53.8%). OGI found intermittent XV-2104 stem plume during load change only; gland re-torqued but load-change re-survey not done. F-205 gasket replaced but torque verification missing. History shows episodes from Sep 15, 88.5% post load changes, rising trend. Emissions methods converge ~0.24-0.31 kg/h favoring XV-2104. Key commitments undone: WO-008-C2, WO-004-C1, WO-012-C1.",
  "findings": [
    {
      "kind": "supporting",
      "statement": "Model alert on recorded footage triggered incident; illustrative origin region overlaps CAM-01 mapping for XV-2104 (61.5%) and F-205 (53.8%); graph confirms assets and connections, not leak causality.",
      "evidence_ids": ["camera:CAM-01/region/XV-2104", "camera:CAM-01/region/F-205", "detection/runs/monitor-mov1237-175-300-001#MOV_1237@204.082", "neo4j:Asset/XV-2104", "neo4j:Asset/F-205"]
    },
    {
      "kind": "supporting",
      "statement": "Quarterly OGI survey (WO-008) found faint intermittent plume at XV-2104 stem packing during 06:00 load change ramp-up; re-shoot at steady load showed no indication; F-205 flange imaged in same frames showed no indication.",
      "evidence_ids": ["field_report:FR-008", "maintenance:WO-008", "commitment:WO-008-C1", "commitment:WO-008-C2"]
    },
    {
      "kind": "supporting",
      "statement": "Gland follower re-torque (WO-009) completed per DS-XV-2104 at steady load; soap test showed no bubbles; repeat OGI survey during load change (WO-008-C2) deferred and not done.",
      "evidence_ids": ["field_report:FR-009", "maintenance:WO-009", "commitment:WO-008-C2", "document:DS-XV-2104#complete_example"]
    },
    {
      "kind": "supporting",
      "statement": "F-205 discharge flange gasket replaced (WO-004) but final bolt torque verification sheet not attached; commitment WO-004-C1 remains open.",
      "evidence_ids": ["field_report:FR-004", "maintenance:WO-004", "commitment:WO-004-C1"]
    },
    {
      "kind": "supporting",
      "statement": "Long-term history: episodes began 2026-09-15, peak at 06:00-08:00 and 17:00-19:00 UTC; 54 of 61 episodes (88.5%) start within 90 min of K-201 load changes (chance 12.5%); weekly episode count and peak ppm rise through Oct; quiet stretches of 9.3, 3.9, 10.5 days with ~35% observability for both assets.",
      "evidence_ids": ["history:HIST-FAC-001:2026-09-06:2026-10-23T19:55:00+00:00", "operations:K-201:load-change-log", "history-episode:EP-20260915-0615", "history-episode:EP-20261022-1745"]
    },
    {
      "kind": "supporting",
      "statement": "Emissions estimation (QOGI, Gaussian, bLs, MDLQ, CFD) converges at 0.24-0.31 kg/h; XV-2104 is best fit across methods; F-205 fit is poor (error ratio 5.66); sensor history shows CH4-01/02/03 at XV-2104 rising while CH4-04/05 at K-201 stay low; PT-2104 pressure rises 12.5->14.0 bar(a).",
      "evidence_ids": ["calculation:INC-001-M031:846:XV-2104", "measurements:SCN-001:846:300", "estimate_emissions"]
    }
  ],
  "candidate_assessment": [
    {
      "asset_id": "XV-2104",
      "assessment": "Best fit across all estimation methods; OGI indication during load change only; gland re-torqued but load-change re-survey (WO-008-C2) not done; hissing reported nearby during load change (WO-012); camera mapping illustrative.",
      "evidence_ids": ["calculation:INC-001-M031:846:XV-2104", "field_report:FR-008", "field_report:FR-009", "field_report:FR-012", "commitment:WO-008-C2", "camera:CAM-01/region/XV-2104", "document:PID-001#complete_example"]
    },
    {
      "asset_id": "F-205",
      "assessment": "Camera overlap but poor sensor fit (error ratio 5.66); no OGI indication in any survey; gasket replaced but bolt torque verification (WO-004-C1) missing; hissing reported between XV-2104 and F-205 but not pinpointed.",
      "evidence_ids": ["calculation:INC-001-M031:846:XV-2104", "field_report:FR-001", "field_report:FR-008", "field_report:FR-004", "field_report:FR-012", "commitment:WO-004-C1", "camera:CAM-01/region/F-205"]
    }
  ],
  "open_questions": [
    "Will the deferred OGI survey during load change (WO-008-C2) be scheduled to test if XV-2104 packing leak persists post re-torque?",
    "Can the missing F-205 bolt torque verification (WO-004-C1) be obtained or repeated to rule out flange leak?",
    "What does the engineering review (WO-012-C1) conclude about the hissing report vs. WO-004 and WO-009 records?",
    "Given the camera mapping is illustrative and uncalibrated, what calibrated survey or alternative method can separate XV-2104 from F-205?"
  ]
}

